import java.util.*;

public class Solution {
    private int[] charToDigit = new int[26];
    private boolean[] usedDigits = new boolean[10];
    private List<Character> chars = new ArrayList<>();
    private Set<Character> leadingChars = new HashSet<>();
    private String[] words;
    private String result;

    public boolean isSolvable(String[] words, String result) {
        this.words = words;
        this.result = result;

        // Collect all unique characters
        boolean[] seen = new boolean[26];
        for (String w : words) {
            for (char c : w.toCharArray()) {
                if (!seen[c - 'A']) {
                    seen[c - 'A'] = true;
                    chars.add(c);
                }
            }
            if (w.length() > 0) leadingChars.add(w.charAt(0));
        }
        for (char c : result.toCharArray()) {
            if (!seen[c - 'A']) {
                seen[c - 'A'] = true;
                chars.add(c);
            }
        }
        if (result.length() > 0) leadingChars.add(result.charAt(0));

        if (chars.size() > 10) return false; // more than digits available

        Arrays.fill(charToDigit, -1);

        return backtrack(0);
    }

    private boolean backtrack(int idx) {
        if (idx == chars.size()) {
            // All chars assigned, check sum
            long sum = 0;
            for (String w : words) {
                long val = wordValue(w);
                if (val == -1) return false; // leading zero
                sum += val;
            }
            long resVal = wordValue(result);
            if (resVal == -1) return false; // leading zero
            return sum == resVal;
        }

        char c = chars.get(idx);
        for (int d = 0; d <= 9; d++) {
            if (usedDigits[d]) continue;
            if (d == 0 && leadingChars.contains(c)) continue; // no leading zero
            charToDigit[c - 'A'] = d;
            usedDigits[d] = true;
            if (backtrack(idx + 1)) return true;
            usedDigits[d] = false;
            charToDigit[c - 'A'] = -1;
        }
        return false;
    }

    private long wordValue(String w) {
        long val = 0;
        for (char c : w.toCharArray()) {
            int d = charToDigit[c - 'A'];
            if (d == -1) return -1; // not assigned yet
            val = val * 10 + d;
        }
        if (w.length() > 1 && charToDigit[w.charAt(0) - 'A'] == 0) return -1; // leading zero
        return val;
    }
}

